function build_dclink2_ripple()
%BUILD_DCLINK2_RIPPLE Create dclink2_ripple.slx from scratch.
%
%   Standalone model of DC link 2 with PI controller 2 and resonant terms at
%   the harmonics of the DC link 1 ripple. All parameters come from
%   dclink2_ripple_params.m (model workspace data source). The model is
%   generated by this script so that its structure is reviewable as text;
%   re-run it after changing the structure, not for parameter changes.
%
%   DC link 1: Vdc1 + sum of harmonics (dclink1_ripple.m); the spectrum
%   switches from the Rload1 to the Rload2 operating point at tStep, together
%   with the load.
%
%   Signals (logged): vdc1, vdc2, iL, m, mRes (resonant part of m).

    here  = fileparts(mfilename('fullpath'));
    model = 'dclink2_ripple';
    file  = fullfile(here, [model '.slx']);
    if bdIsLoaded(model), close_system(model, 0); end
    if isfile(file), delete(file); end

    new_system(model);
    cleanup = onCleanup(@() close_system(model, 0));

    set_param(model, 'Solver', 'ode23tb', 'StopTime', '1.2', 'MaxStep', 'Ts/4', ...
        'RelTol', '1e-6', 'SignalLogging', 'on', 'SignalLoggingName', 'logsout', ...
        'SaveOutput', 'off', 'SaveTime', 'off', 'SaveState', 'off', 'ReturnWorkspaceOutputs', 'on');

    mw = get_param(model, 'ModelWorkspace');
    mw.DataSource = 'MATLAB File';
    mw.FileName = 'dclink2_ripple_params.m';

    b = @(lib, name, pos, varargin) add_block(lib, [model '/' name], 'Position', pos, varargin{:});

    %% DC link 1 with harmonic ripple (not measured)
    b('simulink/Sources/Sine Wave', 'Ripple before step', [40 300 80 340], ...
        'Amplitude', 'ripAmp1', 'Bias', '0', 'Frequency', '2*pi*fg*ripH', 'Phase', 'ripPh1', 'SampleTime', '0');
    b('simulink/Sources/Sine Wave', 'Ripple after step', [40 380 80 420], ...
        'Amplitude', 'ripAmp2', 'Bias', '0', 'Frequency', '2*pi*fg*ripH', 'Phase', 'ripPh2', 'SampleTime', '0');
    b('simulink/Sources/Step', 'Operating point step', [40 340 70 370], ...
        'Time', 'tStep', 'Before', '0', 'After', '1', 'SampleTime', '0');
    b('simulink/Signal Routing/Switch', 'Ripple', [120 315 150 405], 'Criteria', 'u2 > Threshold', 'Threshold', '0.5');
    b('simulink/Math Operations/Sum', 'Sum harmonics', [180 345 210 375], 'Inputs', '+', 'IconShape', 'rectangular');
    b('simulink/Sources/Constant', 'Vdc1', [180 400 220 420], 'Value', 'Vdc1');
    b('simulink/Math Operations/Sum', 'DC link 1', [250 355 270 395], 'Inputs', '++', 'IconShape', 'round');

    %% Setpoint and measurement
    b('simulink/Sources/Constant', 'VbuckSet', [40 95 100 125], 'Value', 'VbuckSet');
    b('simulink/Discrete/Zero-Order Hold', 'ADC', [900 185 935 215], 'SampleTime', 'Ts');
    b('simulink/Math Operations/Sum', 'Error', [150 100 170 140], 'Inputs', '+-', 'IconShape', 'round');

    %% Low-pass on the error (keeps the loop gain away from the LC resonance)
    b('simulink/Discrete/Discrete Transfer Fcn', 'Low-pass', [190 100 260 140], ...
        'Numerator', 'filtNum', 'Denominator', 'filtDen', 'SampleTime', 'Ts');

    %% PI controller 2
    b('simulink/Math Operations/Gain', 'Kp', [300 40 340 70], 'Gain', 'Kp');
    b('simulink/Discrete/Discrete-Time Integrator', 'Integral', [290 95 350 125], ...
        'gainval', 'Ki', 'IntegratorMethod', 'Integration: Forward Euler', 'SampleTime', 'Ts', ...
        'InitialCondition', 'm0', 'LimitOutput', 'on', 'UpperSaturationLimit', 'mMax', ...
        'LowerSaturationLimit', 'mMin');

    %% Resonant terms at the harmonics (sum of biquads, one state-space block)
    b('simulink/Math Operations/Gain', 'Resonant enable', [290 160 340 190], 'Gain', 'resEnable*resGainScale');
    b('simulink/Discrete/Discrete State-Space', 'Resonant terms', [360 155 420 195], ...
        'A', 'resA', 'B', 'resB', 'C', 'resC', 'D', 'resD', 'InitialCondition', '0', 'SampleTime', 'Ts');
    set_param([model '/Resonant terms'], 'Description', ...
        ['Sum over resH of Kr*(s*cos(th) - w*sin(th))/(s^2 + 2*wc*s + w^2), each Tustin prewarped ' ...
         'at w (dclink2_resonant_coeffs.m)']);

    b('simulink/Math Operations/Sum', 'Sum m', [450 85 470 165], 'Inputs', '+++', 'IconShape', 'rectangular');
    b('simulink/Discontinuities/Saturation', 'm limit', [490 110 520 140], ...
        'UpperLimit', 'mMax', 'LowerLimit', 'mMin');
    b('simulink/Discrete/Unit Delay', 'Computation delay', [550 107 585 143], ...
        'InitialCondition', 'm0', 'SampleTime', 'Ts');

    %% Buck power stage (averaged), x = [iL; vC], u = [switch node voltage; load current]
    b('simulink/Math Operations/Product', 'Switch node', [640 115 670 155], 'Inputs', '**');
    b('simulink/Signal Routing/Mux', 'Mux', [700 115 705 195], 'Inputs', '2');
    b('simulink/Continuous/State-Space', 'LC filter', [730 135 830 175], ...
        'A', '[-RL/L, -1/L; 1/C, 0]', 'B', '[1/L, 0; 0, -1/C]', 'C', 'eye(2)', 'D', 'zeros(2)', ...
        'InitialCondition', '[iL0; vC0]');
    b('simulink/Signal Routing/Demux', 'Demux', [860 135 865 175], 'Outputs', '2');
    b('simulink/Sources/Step', 'Load conductance', [560 230 590 260], ...
        'Time', 'tStep', 'Before', '1/Rload1', 'After', '1/Rload2', 'SampleTime', '0');
    b('simulink/Math Operations/Product', 'Load current', [640 210 670 250], 'Inputs', '**');
    b('simulink/Sinks/Terminator', 'iL end', [910 115 930 135]);
    b('simulink/Sinks/Terminator', 'vdc2 end', [980 145 1000 165]);

    %% Wiring
    l = @(src, dst) add_line(model, src, dst, 'autorouting', 'on');
    l('Ripple before step/1', 'Ripple/1');
    l('Operating point step/1', 'Ripple/2');
    l('Ripple after step/1', 'Ripple/3');
    l('Ripple/1', 'Sum harmonics/1');
    l('Sum harmonics/1', 'DC link 1/1');
    l('Vdc1/1', 'DC link 1/2');
    l('VbuckSet/1', 'Error/1');
    l('ADC/1', 'Error/2');
    l('Error/1', 'Low-pass/1');
    l('Low-pass/1', 'Kp/1');
    l('Low-pass/1', 'Integral/1');
    l('Low-pass/1', 'Resonant enable/1');
    l('Resonant enable/1', 'Resonant terms/1');
    l('Kp/1', 'Sum m/1');
    l('Integral/1', 'Sum m/2');
    hRes = l('Resonant terms/1', 'Sum m/3');
    l('Sum m/1', 'm limit/1');
    l('m limit/1', 'Computation delay/1');
    hM = l('Computation delay/1', 'Switch node/1');
    hVdc1 = l('DC link 1/1', 'Switch node/2');
    l('Switch node/1', 'Mux/1');
    l('Load current/1', 'Mux/2');
    l('Mux/1', 'LC filter/1');
    l('LC filter/1', 'Demux/1');
    hIL = l('Demux/1', 'iL end/1');
    hV = l('Demux/2', 'vdc2 end/1');
    l('Demux/2', 'ADC/1');
    l('Demux/2', 'Load current/1');
    l('Load conductance/1', 'Load current/2');

    names = {hRes, 'mRes'; hM, 'm'; hVdc1, 'vdc1'; hIL, 'iL'; hV, 'vdc2'};
    for k = 1:size(names, 1)
        set_param(names{k, 1}, 'Name', names{k, 2});
        set_param(get_param(names{k, 1}, 'SrcPortHandle'), 'DataLogging', 'on');
    end

    a = Simulink.Annotation([model '/note']);
    a.Text = sprintf(['Standalone DC link 2 model. DC link 1 (not measured) carries harmonics of the grid\n' ...
        'frequency (dclink1_ripple.m). PI controller 2: low-pass on the error, P, I, resonant terms at resH.\n' ...
        'Parameters: dclink2_ripple_params.m (model workspace). resEnable = 0: PI only.']);
    a.Position = [40 470 760 520];

    save_system(model, file);
    fprintf('Saved %s\n', file);
end
